{
  "name": "pr-review-dashboard",
  "version": "1.0.0",
  "description": "Local dashboard for PR review automation",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "migrate": "node migrate.js"
  },
  "dependencies": {
    "better-sqlite3": "^11.0.0",
    "cors": "^2.8.5",
    "express": "^4.21.0",
    "marked": "^15.0.0"
  }
}

'use client';
import { useState } from 'react';
import { Button } from './Button';
import { Toast } from './Toast';
import { PaneChooser } from './PaneChooser';
import { api } from '@/lib/api';
import type { Pr } from '@/lib/types';

type ToastMsg = { tone: 'info' | 'success' | 'error'; message: string };

export function PrActions({ pr, onAction }: { pr: Pr; onAction: () => void }) {
  const [busy, setBusy] = useState<string | null>(null);
  const [toast, setToast] = useState<ToastMsg | null>(null);
  const [chooserOpen, setChooserOpen] = useState(false);

  const run = async (key: string, fn: () => Promise<unknown>, successMsg?: string) => {
    setBusy(key);
    try {
      const result: any = await fn();
      onAction();
      if (successMsg) setToast({ tone: 'success', message: successMsg });
      return result;
    } catch (e: any) {
      setToast({ tone: 'error', message: e.message });
      throw e;
    } finally {
      setBusy(null);
    }
  };

  const triggerFixWithPane = async (paneId: string | null) => {
    const result: any = await run(
      'fix',
      () => api.triggerFix(pr.id, paneId ?? undefined),
    );
    setToast({
      tone: 'success',
      message: `Fix → ${result.workspace?.split('/').pop() ?? result.workspace} (${result.window} · ${result.pane_id})`,
    });
  };

  // After any successful merge, post a personalized thank-you comment.
  // First-time contributors get a Discord invite via the welcome route.
  // Best-effort — the merge already succeeded, so we surface the result
  // through the toast but never throw back up.
  const postWelcome = async () => {
    const r = await api.welcome(pr.id);
    if (r.posted) {
      setToast({
        tone: 'success',
        message: r.first_contribution
          ? `Posted welcome + Discord invite to first-time contributor`
          : `Posted thank-you to returning contributor`,
      });
    } else if (r.skipped === 'team_member') {
      setToast({ tone: 'info', message: `Welcome comment skipped: @${r.contributor} is on the team` });
    } else if (r.error) {
      setToast({ tone: 'info', message: `Merge done. Welcome comment skipped: ${r.error.slice(0, 200)}` });
    }
  };

  return (
    <div className="flex flex-wrap gap-2">
      <Button size="sm" onClick={() => run('sync', () => api.syncPr(pr.id))} disabled={busy !== null}>
        {busy === 'sync' ? 'Syncing…' : 'Sync'}
      </Button>

      {pr.is_running ? (
        <Button size="sm" variant="red" onClick={() => run('cancel', () => api.cancelJob(`review-${pr.id}`))} disabled={busy !== null}>
          {busy === 'cancel' ? 'Cancelling…' : 'Cancel Review'}
        </Button>
      ) : (
        <Button size="sm" variant="primary" onClick={() => run('review', () => api.triggerReview(pr.id))} disabled={busy !== null}>
          {busy === 'review' ? 'Starting…' : (pr.cycles?.length ?? 0) > 0 ? 'Trigger Re-review' : 'Trigger Review'}
        </Button>
      )}

      <Button
        size="sm"
        variant="purple"
        onClick={() => setChooserOpen(true)}
        disabled={busy !== null || pr.is_fixing}
        title={pr.is_fixing ? 'Fix already running — attach in tmux' : 'Run `pnpm review fix` in a tmux pane'}
      >
        {busy === 'fix' ? 'Starting…' : pr.is_fixing ? 'Fixing…' : 'Trigger Fix'}
      </Button>

      {pr.status === 'clean' && !pr.is_running && (
        <Button size="sm" variant="green" onClick={() => run('approve', () => api.approve(pr.id))} disabled={busy !== null}>
          {busy === 'approve' ? 'Approving…' : 'Approve'}
        </Button>
      )}

      {pr.status === 'approved' && (
        <Button size="sm" variant="red" onClick={() => run('unapprove', () => api.unapprove(pr.id))} disabled={busy !== null}>
          {busy === 'unapprove' ? 'Unapproving…' : 'Unapprove'}
        </Button>
      )}

      {(pr.status === 'approved' || pr.review_decision === 'APPROVED') && !pr.is_running && (
        <Button
          size="sm"
          variant="purple"
          onClick={async () => {
            if (!confirm(`Merge PR #${pr.id}? (squash + delete branch)`)) return;
            await run('merge', () => api.merge(pr.id), `Merged #${pr.id}`);
            await postWelcome();
          }}
          disabled={busy !== null}
        >
          {busy === 'merge' ? 'Merging…' : 'Merge'}
        </Button>
      )}

      {pr.status === 'clean' && !pr.is_running && (
        <Button
          size="sm"
          variant="purple"
          onClick={async () => {
            if (!confirm(`Approve and merge PR #${pr.id}? (squash + delete branch)`)) return;
            await run('approveMerge', async () => {
              await api.approve(pr.id);
              return api.merge(pr.id);
            }, `Approved + merged #${pr.id}`);
            await postWelcome();
          }}
          disabled={busy !== null}
          title="Post an approving review and then squash-merge"
        >
          {busy === 'approveMerge' ? 'Working…' : 'Approve & Merge'}
        </Button>
      )}

      {!pr.is_running && pr.status !== 'merged' && pr.status !== 'closed' && (
        <Button
          size="sm"
          variant="red"
          onClick={async () => {
            if (!confirm(
              `Force-merge PR #${pr.id}? This bypasses branch protection and failing checks via \`gh pr merge --admin\`. Requires admin rights on the repo.`,
            )) return;
            await run('forceMerge', () => api.merge(pr.id, { force: true }), `Force-merged #${pr.id}`);
            await postWelcome();
          }}
          disabled={busy !== null}
          title="gh pr merge --squash --admin --delete-branch"
        >
          {busy === 'forceMerge' ? 'Force-merging…' : 'Force Merge'}
        </Button>
      )}

      <PaneChooser
        open={chooserOpen}
        onClose={() => setChooserOpen(false)}
        onPick={triggerFixWithPane}
      />
      {toast && <Toast tone={toast.tone} message={toast.message} onClose={() => setToast(null)} />}
    </div>
  );
}

// Shared auth module for dashboard frontend
function getApiKey() {
  let key = localStorage.getItem('api_key');
  if (!key) {
    key = prompt('Enter API key (from .env):');
    if (key) localStorage.setItem('api_key', key);
  }
  return key;
}

function authHeaders() {
  const key = getApiKey();
  return key ? { 'Authorization': `Bearer ${key}` } : {};
}

async function authFetch(url, opts = {}) {
  opts.headers = { ...opts.headers, ...authHeaders() };
  const res = await fetch(url, opts);
  if (res.status === 401) {
    localStorage.removeItem('api_key');
    alert('Invalid API key — please re-enter');
    location.reload();
    throw new Error('Unauthorized');
  }
  return res;
}

const express = require('express');
const fs = require('fs');
const path = require('path');
const { marked } = require('marked');
const db = require('../db');
const sync = require('../sync');
const githubSync = require('../github-sync');
const triggerRouter = require('./trigger');
const { scanTrackingDir } = require('../parser');

const router = express.Router();

// Auth check for mutation endpoints within /api
function checkAuth(req, res, next) {
  const key = process.env.API_KEY;
  if (!key) return next();
  const header = req.headers['authorization']?.replace('Bearer ', '');
  if (header === key) return next();
  res.status(401).json({ error: 'Unauthorized' });
}

const BASE_DIR = path.resolve(__dirname, '../..');
const TRACKING_DIR = path.join(BASE_DIR, 'tinyhumansai-openhuman');
const APPROVED_DIR = path.join(BASE_DIR, 'to-be-approved');
const FULLY_APPROVED_DIR = path.join(BASE_DIR, 'approved');
const LOGS_DIR = path.join(BASE_DIR, 'logs');

// GET /api/stats
router.get('/stats', (req, res) => {
  const stats = db.getStats();
  const liveStatus = sync.getLiveStatus();
  res.json({ ...stats, liveStatus });
});

// GET /api/prs?status=pending&author=oxoxDev&member=1&draft=0&mergeable=MERGEABLE&...
router.get('/prs', (req, res) => {
  const filters = {
    status: req.query.status || undefined,
    author: req.query.author || undefined,
    member: req.query.member,
    draft: req.query.draft,
    mergeable: req.query.mergeable || undefined,
    review_decision: req.query.review_decision || undefined,
    label: req.query.label || undefined,
    has_review: req.query.has_review,
    has_findings: req.query.has_findings,
    merge_state: req.query.merge_state || undefined,
    is_open: req.query.is_open,
    assignee: req.query.assignee || undefined,
    reviewer: req.query.reviewer || undefined,
    search: req.query.search || undefined,
    min_additions: req.query.min_additions || undefined,
    max_additions: req.query.max_additions || undefined,
    min_deletions: req.query.min_deletions || undefined,
    max_deletions: req.query.max_deletions || undefined,
    created_after: req.query.created_after || undefined,
    created_before: req.query.created_before || undefined,
    ci_status: req.query.ci_status || undefined,
    include_merged: req.query.include_merged === '1' || undefined,
    sort: req.query.sort || undefined,
    order: req.query.order || undefined,
  };

  const prs = db.queryPrs(filters);
  const liveStatus = sync.getLiveStatus();
  const activeJobs = triggerRouter.activeJobs;

  const enriched = prs.map(pr => {
    const job = activeJobs.get(`review-${pr.id}`);
    // If job exists (running or done), trust it over status.json
    const statusRunning = liveStatus && liveStatus.running && liveStatus.pr === pr.id;
    const isRunning = job ? !job.done : statusRunning;

    return {
      ...pr,
      is_running: isRunning,
    };
  });

  res.json(enriched);
});

// GET /api/filters — distinct values for filter dropdowns
router.get('/filters', (req, res) => {
  const options = db.getFilterOptions();
  res.json(options);
});

// GET /api/prs/:id
router.get('/prs/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const pr = db.getPrByIdFull(id);
  if (!pr) return res.status(404).json({ error: 'PR not found' });

  const cycles = db.getCyclesByPr(id);
  const liveStatus = sync.getLiveStatus();
  const job = triggerRouter.activeJobs.get(`review-${id}`);
  const statusRunning = liveStatus && liveStatus.running && liveStatus.pr === id;
  const isRunning = job ? !job.done : statusRunning;

  res.json({
    ...pr,
    cycles,
    is_running: isRunning,
  });
});

// GET /api/prs/:id/checks — parsed CI checks
router.get('/prs/:id/checks', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const pr = db.getPrByIdFull(id);
  if (!pr) return res.status(404).json({ error: 'PR not found' });

  let checks = [];
  if (pr.ci_checks) {
    try { checks = JSON.parse(pr.ci_checks); } catch {}
  }

  res.json({
    total: pr.ci_total || 0,
    pass: pr.ci_pass || 0,
    fail: pr.ci_fail || 0,
    pending: pr.ci_pending || 0,
    checks,
  });
});

// GET /api/prs/:id/tracking — raw markdown
router.get('/prs/:id/tracking', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const pr = db.getPrById(id);
  if (!pr) return res.status(404).json({ error: 'PR not found' });

  const filePath = pr.tracking_file_path;
  if (!filePath || !fs.existsSync(filePath)) {
    return res.status(404).json({ error: 'Tracking file not found' });
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  res.type('text/plain').send(content);
});

// GET /api/prs/:id/tracking/html — rendered markdown
router.get('/prs/:id/tracking/html', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const pr = db.getPrById(id);
  if (!pr) return res.status(404).json({ error: 'PR not found' });

  const filePath = pr.tracking_file_path;
  if (!filePath || !fs.existsSync(filePath)) {
    return res.status(404).json({ error: 'Tracking file not found' });
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  const html = marked(content);
  res.type('text/html').send(html);
});

// GET /api/prs/:id/log/:cycle — raw log for a review cycle
router.get('/prs/:id/log/:cycle', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const cycleNum = parseInt(req.params.cycle, 10);

  const cycles = db.getCyclesByPr(id);
  const cycle = cycles.find(c => c.cycle_number === cycleNum);

  if (!cycle || !cycle.log_file_path || !fs.existsSync(cycle.log_file_path)) {
    // Try to find a matching log file by PR number
    const logPattern = new RegExp(`review-PR-${id}.*\\.log$`);
    const logFiles = fs.existsSync(LOGS_DIR)
      ? fs.readdirSync(LOGS_DIR).filter(f => logPattern.test(f)).sort()
      : [];

    if (logFiles.length > 0 && logFiles[cycleNum - 1]) {
      const content = fs.readFileSync(path.join(LOGS_DIR, logFiles[cycleNum - 1]), 'utf-8');
      return res.type('text/plain').send(content);
    }

    return res.status(404).json({ error: 'Log not found' });
  }

  const content = fs.readFileSync(cycle.log_file_path, 'utf-8');
  res.type('text/plain').send(content);
});

// GET /api/prs/:id/logs — list all log files for a PR
router.get('/prs/:id/logs', (req, res) => {
  const id = parseInt(req.params.id, 10);

  const logPattern = new RegExp(`review-PR-${id}.*\\.log$`);
  const logFiles = fs.existsSync(LOGS_DIR)
    ? fs.readdirSync(LOGS_DIR).filter(f => logPattern.test(f)).sort()
    : [];

  const logs = logFiles.map(f => ({
    filename: f,
    path: path.join(LOGS_DIR, f),
    size: fs.statSync(path.join(LOGS_DIR, f)).size,
  }));

  res.json(logs);
});

// GET /api/cron-runs
router.get('/cron-runs', (req, res) => {
  const runs = db.getAllCronRuns();
  res.json(runs);
});

// GET /api/status — live review status
router.get('/status', (req, res) => {
  const liveStatus = sync.getLiveStatus();
  res.json(liveStatus || { running: false });
});

// POST /api/prs/:id/sync — sync a single PR (GitHub + tracking file)
router.post('/prs/:id/sync', checkAuth, (req, res) => {
  const id = parseInt(req.params.id, 10);
  try {
    // Re-parse tracking file if it exists
    const existing = db.getPrById(id);
    if (existing && existing.tracking_file_path && fs.existsSync(existing.tracking_file_path)) {
      sync.syncFile(existing.tracking_file_path, existing.location);
    }

    // Re-fetch from GitHub API
    const updated = githubSync.fetchSinglePr(id);

    // Return full PR data with cycles
    const cycles = db.getCyclesByPr(id);
    res.json({ ...updated, cycles, synced: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/sync — force re-sync from files
router.post('/sync', checkAuth, (req, res) => {
  try {
    const trackingPrs = scanTrackingDir(TRACKING_DIR, 'tinyhumansai-openhuman');
    const approvedPrs = scanTrackingDir(APPROVED_DIR, 'to-be-approved');
    const fullyApprovedPrs = scanTrackingDir(FULLY_APPROVED_DIR, 'approved');
    const toBeClosedPrs = scanTrackingDir(path.join(BASE_DIR, 'to-be-closed'), 'to-be-closed');
    const allPrs = [...trackingPrs, ...approvedPrs, ...fullyApprovedPrs, ...toBeClosedPrs];

    for (const { pr, cycles } of allPrs) {
      if (!pr.id) continue;
      db.upsertPr({
        id: pr.id,
        title: pr.title,
        author: pr.author,
        branch: pr.branch,
        base_branch: pr.base_branch,
        url: pr.url,
        created_at: pr.created_at,
        status: pr.status,
        is_member: null,
        last_reviewed_commit: pr.last_reviewed_commit,
        last_review_date: pr.last_review_date,
        tracking_file_path: pr.tracking_file_path,
        location: pr.location,
      });
      if (cycles.length > 0) {
        db.replaceCyclesForPr(pr.id, cycles);
      }
    }

    // Also refresh from GitHub
    githubSync.fetchAllOpenPrs();

    res.json({ synced: allPrs.length, github: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// POST /api/github-sync — force GitHub re-fetch
router.post('/github-sync', checkAuth, (req, res) => {
  try {
    githubSync.fetchAllOpenPrs();
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

module.exports = router;

import type { Pr, Stats, FilterOptions, Job, PrFilters, CiCheck, GhPr, GhFile, GhComment } from './types';

export const GH_REPO = 'tinyhumansai/openhuman';
const GH_API = `https://api.github.com/repos/${GH_REPO}`;

async function jget<T>(url: string): Promise<T> {
  const res = await fetch(url, { cache: 'no-store' });
  if (!res.ok) throw new Error(`${res.status} ${res.statusText} on ${url}`);
  return res.json();
}

async function jpost<T>(url: string): Promise<T> {
  const res = await fetch(url, { method: 'POST', cache: 'no-store' });
  if (!res.ok) {
    const err = await res.json().catch(() => ({ error: res.statusText }));
    throw new Error(err.error || `${res.status}`);
  }
  return res.json();
}

export const api = {
  whoami: () => jget<{ login: string | null; name: string | null }>('/api/whoami'),
  openPulls: () => jget<{ ids: number[]; cached?: boolean }>('/api/open-pulls'),
  stats: () => jget<Stats>('/api/stats'),
  filters: () => jget<FilterOptions>('/api/filters'),
  prs: (filters: PrFilters = {}) => {
    const sp = new URLSearchParams();
    for (const [k, v] of Object.entries(filters)) {
      if (v !== undefined && v !== null && v !== '') sp.set(k, String(v));
    }
    const qs = sp.toString();
    return jget<Pr[]>(`/api/prs${qs ? `?${qs}` : ''}`);
  },
  pr: (id: number) => jget<Pr>(`/api/prs/${id}`),
  prChecks: (id: number, refresh = false) =>
    jget<{ checks: CiCheck[]; total: number; pass: number; fail: number; pending: number; refreshed?: boolean }>(
      `/api/prs/${id}/checks${refresh ? '?refresh=1' : ''}`,
    ),
  prTrackingHtml: async (id: number): Promise<string | null> => {
    const r = await fetch(`/api/prs/${id}/tracking/html`);
    return r.ok ? r.text() : null;
  },
  prLogs: (id: number) => jget<Array<{ filename: string; path: string; size: number }>>(`/api/prs/${id}/logs`),
  jobs: () => jget<Record<string, Job>>('/api/trigger/jobs'),
  jobLog: (jobId: string, after = 0) =>
    jget<{ jobId: string; done: boolean; exitCode: number | null; total: number; after: number; lines: string[] }>(
      `/api/trigger/log/${encodeURIComponent(jobId)}?after=${after}`,
    ),
  // Mutations
  triggerReview: (id: number) => jpost<{ jobId: string; message: string }>(`/api/trigger/review/${id}`),
  triggerFix: async (id: number, paneId?: string) => {
    const res = await fetch(`/api/trigger/fix/${id}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      cache: 'no-store',
      body: JSON.stringify(paneId ? { pane_id: paneId } : {}),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({ error: res.statusText }));
      throw new Error(err.error || `${res.status}`);
    }
    return res.json() as Promise<{
      pr: number;
      session: string;
      window: string;
      pane_id: string;
      workspace: string;
      attach: string;
      logFile: string;
      message: string;
    }>;
  },
  fixStatus: (id: number, lines = 400) =>
    jget<{
      running: boolean;
      mapping: { pane_id: string; window: string; workspace: string; logFile: string; started_at: string } | null;
      content: string | null;
    }>(`/api/trigger/fix/${id}?lines=${lines}`),
  fixSend: async (id: number, payload: { text?: string; key?: string }) => {
    const res = await fetch(`/api/trigger/fix/${id}/send`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      cache: 'no-store',
      body: JSON.stringify(payload),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({ error: res.statusText }));
      throw new Error(err.error || `${res.status}`);
    }
    return res.json() as Promise<{ sent: boolean; pane_id: string }>;
  },
  listPanes: () =>
    jget<{
      session: string | null;
      panes: Array<{ pane_id: string; window: string; command: string; cwd: string; workspace: string; idle: boolean }>;
    }>('/api/trigger/panes'),
  triggerDiscover: () => jpost<{ jobId: string }>('/api/trigger/discover'),
  cancelJob: (jobId: string) => jpost<{ message: string }>(`/api/trigger/cancel/${encodeURIComponent(jobId)}`),
  approve: (id: number) => jpost<{ success: boolean; review_url?: string }>(`/api/trigger/approve/${id}`),
  unapprove: (id: number) => jpost<{ success: boolean }>(`/api/trigger/unapprove/${id}`),
  mergePreflight: (id: number) => jget<{ checks: Array<{ name: string; pass: boolean }>; allPass: boolean }>(`/api/trigger/merge-preflight/${id}`),
  merge: async (id: number, opts: { force?: boolean } = {}) => {
    const res = await fetch(`/api/trigger/merge/${id}`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      cache: 'no-store',
      body: JSON.stringify({ force: opts.force === true }),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({ error: res.statusText }));
      throw new Error(err.error || `${res.status}`);
    }
    return res.json() as Promise<{ success: boolean; force?: boolean; message: string }>;
  },
  syncPr: (id: number) => jpost<Pr>(`/api/prs/${id}/sync`),
  syncAll: () => jpost<{ synced: number }>('/api/sync'),
  // Best-effort post-merge welcome. Errors here shouldn't bubble up — the
  // merge has already succeeded by the time we call this.
  welcome: async (id: number) => {
    try {
      return await jpost<{ posted: boolean; first_contribution?: boolean; comment?: string; error?: string; skipped?: string; contributor?: string }>(
        `/api/trigger/welcome/${id}`,
      );
    } catch (e: any) {
      return { posted: false, error: e.message };
    }
  },
};

// Public GitHub API — direct from browser (repo is public).
export const gh = {
  pr: (id: number) => jget<GhPr>(`${GH_API}/pulls/${id}`),
  files: (id: number) => jget<GhFile[]>(`${GH_API}/pulls/${id}/files?per_page=100`),
  comments: async (id: number): Promise<GhComment[]> => {
    const [issue, review] = await Promise.all([
      fetch(`${GH_API}/issues/${id}/comments?per_page=100`).then((r) => (r.ok ? r.json() : [])),
      fetch(`${GH_API}/pulls/${id}/comments?per_page=100`).then((r) => (r.ok ? r.json() : [])),
    ]);
    const all: GhComment[] = [
      ...issue.map((c: any) => ({ ...c, kind: 'issue' as const })),
      ...review.map((c: any) => ({ ...c, kind: 'review' as const })),
    ];
    return all.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());
  },
  diffUrl: (id: number) => `https://github.com/${GH_REPO}/pull/${id}/files`,
  prUrl: (id: number) => `https://github.com/${GH_REPO}/pull/${id}`,

  // Set of PR numbers currently open on GitHub. Used as the source of truth
  // for filtering merged/closed PRs out of the dashboard without touching the
  // local DB. Paginates up to 4 pages (400 PRs) which is plenty for this repo.
  //
  // Cached for 2 min in-memory: unauthenticated GitHub allows 60 req/hr per
  // IP, so polling every 30s would burn the budget in ~30 min. With a 2-min
  // cache, the dashboard issues at most ~30 GitHub calls/hr regardless of
  // local poll cadence.
  async openPullNumbers(): Promise<Set<number>> {
    const now = Date.now();
    if (_openPullsCache && now - _openPullsCache.at < OPEN_PULLS_TTL_MS) {
      return _openPullsCache.ids;
    }
    const ids = new Set<number>();
    for (let page = 1; page <= 4; page++) {
      const r = await fetch(`${GH_API}/pulls?state=open&per_page=100&page=${page}`);
      if (!r.ok) {
        // If we already have a stale snapshot, keep returning it instead of
        // an empty set so the UI doesn't accidentally hide everything.
        if (_openPullsCache) return _openPullsCache.ids;
        throw new Error(`${r.status} from GitHub`);
      }
      const batch: Array<{ number: number }> = await r.json();
      for (const p of batch) ids.add(p.number);
      if (batch.length < 100) break;
    }
    _openPullsCache = { ids, at: now };
    return ids;
  },
};

const OPEN_PULLS_TTL_MS = 2 * 60 * 1000;
let _openPullsCache: { ids: Set<number>; at: number } | null = null;

import { NextRequest, NextResponse } from 'next/server';
import { db, sync, triggerJobs, tmux } from '@/lib/server-deps';

export const dynamic = 'force-dynamic';

const FILTER_KEYS = [
  'status', 'author', 'member', 'draft', 'mergeable', 'review_decision',
  'label', 'has_review', 'has_findings', 'merge_state', 'is_open',
  'assignee', 'reviewer', 'search', 'min_additions', 'max_additions',
  'min_deletions', 'max_deletions', 'created_after', 'created_before',
  'ci_status', 'sort', 'order',
];

export async function GET(req: NextRequest) {
  const sp = req.nextUrl.searchParams;
  const filters: Record<string, any> = {};
  for (const k of FILTER_KEYS) {
    const v = sp.get(k);
    if (v !== null && v !== '') filters[k] = v;
  }
  if (sp.get('include_merged') === '1') filters.include_merged = true;

  const prs = db.queryPrs(filters);
  const liveStatus = sync.getLiveStatus();
  const activeJobs = triggerJobs.activeJobs;

  const enriched = prs.map((pr: any) => {
    const job = activeJobs.get(`review-${pr.id}`);
    const statusRunning = liveStatus && liveStatus.running && liveStatus.pr === pr.id;
    const tmuxRunning = tmux.isRunning(pr.id);
    const tmuxWindow = tmux.hasWindow(pr.id) ? `${tmux.SESSION}:pr-${pr.id}` : null;
    const isRunning = job ? !job.done : tmuxRunning || statusRunning;
    return { ...pr, is_running: isRunning, tmux_window: tmuxWindow };
  });

  return NextResponse.json(enriched);
}

