import { NextResponse } from 'next/server';
import path from 'path';
import { db, githubSync, parser } from '@/lib/server-deps';

export const dynamic = 'force-dynamic';

const BASE_DIR = path.resolve(process.cwd(), '..');
const TRACKING_DIR = path.join(BASE_DIR, 'tinyhumansai-openhuman');
const APPROVED_DIR = path.join(BASE_DIR, 'to-be-approved');
const FULLY_APPROVED_DIR = path.join(BASE_DIR, 'approved');

export async function POST() {
  try {
    const trackingPrs = parser.scanTrackingDir(TRACKING_DIR, 'tinyhumansai-openhuman');
    const approvedPrs = parser.scanTrackingDir(APPROVED_DIR, 'to-be-approved');
    const fullyApprovedPrs = parser.scanTrackingDir(FULLY_APPROVED_DIR, 'approved');
    const allPrs = [...trackingPrs, ...approvedPrs, ...fullyApprovedPrs];

    for (const { pr, cycles } of allPrs) {
      if (!pr.id) continue;
      db.upsertPr({
        id: pr.id,
        title: pr.title,
        author: pr.author,
        branch: pr.branch,
        base_branch: pr.base_branch,
        url: pr.url,
        created_at: pr.created_at,
        status: pr.status,
        is_member: null,
        last_reviewed_commit: pr.last_reviewed_commit,
        last_review_date: pr.last_review_date,
        tracking_file_path: pr.tracking_file_path,
        location: pr.location,
      });
      if (cycles.length > 0) db.replaceCyclesForPr(pr.id, cycles);
    }

    githubSync.fetchAllOpenPrs();
    return NextResponse.json({ synced: allPrs.length, github: true });
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { execSync } from 'child_process';

export const dynamic = 'force-dynamic';

const REPO = 'tinyhumansai/openhuman';

// Returns the set of currently-open PR numbers using the authenticated gh
// CLI (5000 req/hr) instead of hitting the public api.github.com from the
// browser (60 req/hr per IP) which we'd burn through within minutes.
// Server-side cache keeps load down further.
let _cache: { ids: number[]; at: number } | null = null;
const TTL_MS = 60 * 1000;

export async function GET() {
  const now = Date.now();
  if (_cache && now - _cache.at < TTL_MS) {
    return NextResponse.json({ ids: _cache.ids, cached: true });
  }
  try {
    const out = execSync(
      `gh pr list --repo ${REPO} --state open --limit 500 --json number --jq '[.[].number]'`,
      { encoding: 'utf-8', timeout: 20000, stdio: ['pipe', 'pipe', 'pipe'] },
    );
    const ids: number[] = JSON.parse(out);
    _cache = { ids, at: now };
    return NextResponse.json({ ids, cached: false });
  } catch (err: any) {
    const msg = (err.stderr || err.message || '').toString();
    if (_cache) {
      // Surface stale list rather than empty so the UI doesn't blank out.
      return NextResponse.json({ ids: _cache.ids, cached: true, error: msg }, { status: 200 });
    }
    return NextResponse.json({ ids: [], error: msg }, { status: 500 });
  }
}

