import { NextResponse } from 'next/server';
import path from 'path';
import { triggerJobs } from '@/lib/server-deps';

export const dynamic = 'force-dynamic';

const CRON_SCRIPT = path.join(triggerJobs.BASE_DIR, 'cron-pr-review.sh');

export async function POST() {
  if (triggerJobs.activeJobs.has('discover')) {
    return NextResponse.json({ error: 'Discovery is already running' }, { status: 409 });
  }

  const logFile = path.join(triggerJobs.LOGS_DIR, `review-${triggerJobs.timestamp()}.log`);
  const job = triggerJobs.startJob({
    jobId: 'discover',
    command: 'bash',
    args: [CRON_SCRIPT],
    logFile,
    type: 'discover',
    pr: null,
    onClose: (code: number) => console.log(`[trigger] Discovery finished with code ${code}`),
  });

  if (!job) {
    return NextResponse.json({ error: 'Job already running' }, { status: 409 });
  }

  return NextResponse.json({ jobId: 'discover', pid: job.pid, logFile, message: 'Discovery started' });
}

import { NextResponse } from 'next/server';
import { tmux } from '@/lib/server-deps';

export const dynamic = 'force-dynamic';

// List of openhuman-* panes plus their idle/busy state. The UI uses this to
// let the user pick which pane to send a fix into.
export async function GET() {
  if (!tmux.isAvailable() || !tmux.sessionExists()) {
    return NextResponse.json({ session: null, panes: [] });
  }

  // Panes already running an in-flight fix shouldn't appear as idle even
  // when their tmux pane_current_command is still a shell — pnpm/claude
  // hasn't started yet but the keystrokes are already queued.
  const reserved: Set<string> = tmux.reservedPaneIds();

  const panes = tmux.listPanes()
    .filter((p: any) => /\/openhuman-\d+(?:\/|$)/.test(p.cwd || ''))
    .map((p: any) => {
      const shellIdle = ['bash', 'zsh', 'sh', 'fish'].includes(p.command);
      const isReserved = reserved.has(p.pane_id);
      return {
        pane_id: p.pane_id,
        window: p.window,
        command: isReserved ? `${p.command} (fix queued)` : p.command,
        cwd: p.cwd,
        workspace: p.cwd?.match(/\/openhuman-\d+/)?.[0]?.slice(1) ?? p.cwd,
        idle: shellIdle && !isReserved,
        reserved: isReserved,
      };
    })
    .sort((a: any, b: any) => {
      // idle first, then by workspace number
      if (a.idle !== b.idle) return a.idle ? -1 : 1;
      const an = parseInt(a.workspace.match(/\d+/)?.[0] ?? '0', 10);
      const bn = parseInt(b.workspace.match(/\d+/)?.[0] ?? '0', 10);
      return an - bn;
    });

  return NextResponse.json({ session: tmux.SESSION, panes });
}

import { NextResponse } from 'next/server';
import { db, sync, triggerJobs, tmux } from '@/lib/server-deps';

export const dynamic = 'force-dynamic';

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id: idStr } = await params;
  const id = parseInt(idStr, 10);
  const pr = db.getPrByIdFull(id);
  if (!pr) return NextResponse.json({ error: 'PR not found' }, { status: 404 });

  const cycles = db.getCyclesByPr(id);
  const liveStatus = sync.getLiveStatus();
  const job = triggerJobs.activeJobs.get(`review-${id}`);
  const statusRunning = liveStatus && liveStatus.running && liveStatus.pr === id;
  const tmuxRunning = tmux.isRunning(id);
  const tmuxWindow = tmux.hasWindow(id) ? `${tmux.SESSION}:pr-${id}` : null;
  const tmuxExit = tmuxWindow ? tmux.exitCode(id) : null;
  const fixRunning = tmux.isFixRunning(id);
  const fixMapping = tmux.getFixMapping(id);
  const fixWindow = fixMapping
    ? `${tmux.SESSION}:${fixMapping.window}`
    : tmux.listWindows().includes(`fix-${id}`)
    ? `${tmux.SESSION}:fix-${id}`
    : null;
  const isRunning = job ? !job.done : tmuxRunning || statusRunning;

  return NextResponse.json({
    ...pr,
    cycles,
    is_running: isRunning,
    is_fixing: fixRunning,
    tmux_window: tmuxWindow,
    tmux_exit_code: tmuxExit,
    tmux_fix_window: fixWindow,
  });
}

