import { NextRequest, NextResponse } from 'next/server';
import { triggerJobs } from '@/lib/server-deps';

export const dynamic = 'force-dynamic';

export async function GET(req: NextRequest, { params }: { params: Promise<{ jobId: string }> }) {
  const { jobId } = await params;
  const after = parseInt(req.nextUrl.searchParams.get('after') || '0', 10);

  const job = triggerJobs.activeJobs.get(jobId);
  if (!job) return NextResponse.json({ error: 'Job not found' }, { status: 404 });

  const lines = job.logLines.slice(after);
  return NextResponse.json({
    jobId,
    done: job.done,
    exitCode: job.exitCode,
    startedAt: job.startedAt,
    endedAt: job.endedAt || null,
    total: job.logLines.length,
    after,
    lines,
  });
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import { db } from '@/lib/server-deps';

export const dynamic = 'force-dynamic';

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id: idStr } = await params;
  const id = parseInt(idStr, 10);
  const pr = db.getPrById(id);
  if (!pr) return NextResponse.json({ error: 'PR not found' }, { status: 404 });

  const filePath = pr.tracking_file_path;
  if (!filePath || !fs.existsSync(filePath)) {
    return NextResponse.json({ error: 'Tracking file not found' }, { status: 404 });
  }

  const content = fs.readFileSync(filePath, 'utf-8');
  return new NextResponse(content, { headers: { 'content-type': 'text/plain; charset=utf-8' } });
}

import { NextResponse } from 'next/server';
import fs from 'fs';
import { db, sync, githubSync } from '@/lib/server-deps';

export const dynamic = 'force-dynamic';

export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id: idStr } = await params;
  const id = parseInt(idStr, 10);
  try {
    const existing = db.getPrById(id);
    if (existing && existing.tracking_file_path && fs.existsSync(existing.tracking_file_path)) {
      sync.syncFile(existing.tracking_file_path, existing.location);
    }
    const updated = githubSync.fetchSinglePr(id);
    const cycles = db.getCyclesByPr(id);
    return NextResponse.json({ ...updated, cycles, synced: true });
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}
